#include <JuceHeader.h>
#include "../Musician/Core/Musician.h"

namespace covertracks {

/**
 * Real-world musical pattern tests for Music JSON 2.0
 * Tests actual musical examples that could be generated by LLMs
 */
class MusicJson2RealWorldTests : public juce::UnitTest
{
public:
    MusicJson2RealWorldTests() : juce::UnitTest("Music JSON 2.0 Real World", "Music Pattern System") {}
    
    void runTest() override
    {
        testJazzStandardPattern();
        testRockSongStructure();
        testClassicalPhrasing();
        testElectronicGroove();
        testLLMGeneratedPattern();
    }
    
private:
    void testJazzStandardPattern()
    {
        beginTest("Jazz Standard - Autumn Leaves style");
        
        juce::String autumnLeavesStyle = R"({
            "version": "2.0",
            "meta": {
                "title": "Autumn Leaves Style",
                "tempo": 120,
                "style": "jazz",
                "timeSignature": "4/4"
            },
            "context": {
                "key": "Bb major",
                "velocity": 0.75,
                "dynamics": "mf"
            },
            "patterns": {
                "swingDrums": {
                    "events": [
                        {"t": 1.0, "n": "kick", "v": 0.8, "dur": 0.25},
                        {"t": 1.33, "n": "hihat", "v": 0.4, "dur": 0.1},
                        {"t": 2.0, "n": "snare", "v": 0.7, "dur": 0.25},
                        {"t": 2.67, "n": "hihat", "v": 0.4, "dur": 0.1},
                        {"t": 3.0, "n": "kick", "v": 0.6, "dur": 0.25},
                        {"t": 3.33, "n": "hihat", "v": 0.4, "dur": 0.1},
                        {"t": 4.0, "n": "snare", "v": 0.7, "dur": 0.25},
                        {"t": 4.67, "n": "hihat", "v": 0.4, "dur": 0.1}
                    ]
                },
                "walkingBass": {
                    "context": {"octave": 2, "articulation": "legato"},
                    "events": [
                        {"t": 1.0, "d": 1, "dur": 1.0, "v": 0.8},
                        {"t": 2.0, "d": 3, "dur": 1.0, "v": 0.7},
                        {"t": 3.0, "d": 5, "dur": 1.0, "v": 0.7},
                        {"t": 4.0, "d": 7, "dur": 1.0, "v": 0.8}
                    ]
                },
                "pianoComping": {
                    "context": {"octave": 4, "articulation": "staccato"},
                    "events": [
                        {"t": 1.5, "d": 3, "dur": 0.5, "v": 0.6},
                        {"t": 1.5, "d": 7, "dur": 0.5, "v": 0.6},
                        {"t": 3.0, "d": 1, "dur": 0.5, "v": 0.7},
                        {"t": 3.0, "d": 5, "dur": 0.5, "v": 0.7},
                        {"t": 4.5, "d": 3, "dur": 0.5, "v": 0.6},
                        {"t": 4.5, "d": 7, "dur": 0.5, "v": 0.6}
                    ]
                }
            },
            "sections": {
                "AABA": {
                    "context": {"chordProgression": ["Cm7", "F7", "BbMaj7", "EbMaj7"]},
                    "layers": {
                        "drums": {"pattern": "swingDrums"},
                        "bass": {
                            "pattern": "walkingBass",
                            "variations": {
                                "bar2": {"context": {"chord": "F7"}},
                                "bar3": {"context": {"chord": "BbMaj7"}},
                                "bar4": {"context": {"chord": "EbMaj7"}}
                            }
                        },
                        "piano": {
                            "pattern": "pianoComping",
                            "variations": {
                                "bar2": {"context": {"chord": "F7"}},
                                "bar3": {"context": {"chord": "BbMaj7"}},
                                "bar4": {"context": {"chord": "EbMaj7"}}
                            }
                        },
                        "melody": {
                            "context": {"octave": 5, "velocity": 0.9, "articulation": "legato"},
                            "events": [
                                {"t": 1.5, "d": 5, "dur": 1.5, "dynamics": "f"},
                                {"t": 3.0, "d": 3, "dur": 1.0, "dynamics": "mf"},
                                {"t": 4.0, "d": 1, "dur": 1.0, "dynamics": "mf"}
                            ]
                        }
                    }
                }
            }
        })";
        
        auto musician = std::make_unique<Musician>("jazz-test", "jazz");
        auto result = musician->convertNotationToMidiEvents(autumnLeavesStyle, 120.0);
        
        expect(result.getProperty("success", false), "Jazz standard should parse successfully");
        
        auto events = result["events"];
        if (events.isArray()) {
            expect(events.getArray()->size() > 0, "Should generate jazz events");
            logMessage("Generated " + juce::String(events.getArray()->size()) + " jazz events");
        }
        
        logMessage("Jazz standard pattern working");
    }
    
    void testRockSongStructure()
    {
        beginTest("Rock Song - Verse/Chorus/Bridge structure");
        
        juce::String rockSong = R"({
            "version": "2.0",
            "meta": {
                "title": "Rock Anthem",
                "tempo": 130,
                "style": "rock",
                "key": "E minor"
            },
            "context": {
                "velocity": 0.8,
                "dynamics": "f"
            },
            "patterns": {
                "rockBeat": {
                    "events": [
                        {"t": 1.0, "n": "kick", "v": 0.9, "dur": 0.25},
                        {"t": 2.0, "n": "snare", "v": 0.8, "dur": 0.25},
                        {"t": 2.5, "n": "hihat", "v": 0.5, "dur": 0.1},
                        {"t": 3.0, "n": "kick", "v": 0.7, "dur": 0.25},
                        {"t": 4.0, "n": "snare", "v": 0.8, "dur": 0.25}
                    ]
                },
                "powerChords": {
                    "context": {"octave": 3, "articulation": "marcato"},
                    "events": [
                        {"t": 1.0, "d": 1, "dur": 2.0, "v": 0.9},
                        {"t": 1.0, "d": 5, "dur": 2.0, "v": 0.9},
                        {"t": 3.0, "d": 4, "dur": 2.0, "v": 0.8},
                        {"t": 3.0, "d": 1, "dur": 2.0, "v": 0.8}
                    ]
                },
                "bassRiff": {
                    "context": {"octave": 2, "articulation": "staccato"},
                    "events": [
                        {"t": 1.0, "d": 1, "dur": 0.5, "v": 0.8},
                        {"t": 1.5, "d": 1, "dur": 0.5, "v": 0.7},
                        {"t": 2.0, "d": 3, "dur": 0.5, "v": 0.8},
                        {"t": 3.0, "d": 5, "dur": 1.0, "v": 0.9}
                    ]
                }
            },
            "sections": {
                "verse": {
                    "context": {"chord": "Em", "dynamics": "mf"},
                    "layers": {
                        "drums": {"pattern": "rockBeat"},
                        "guitar": {"pattern": "powerChords"},
                        "bass": {"pattern": "bassRiff"}
                    }
                },
                "chorus": {
                    "context": {"chord": "C", "dynamics": "ff"},
                    "layers": {
                        "drums": {
                            "pattern": "rockBeat",
                            "context": {"velocity": 1.0}
                        },
                        "guitar": {
                            "pattern": "powerChords",
                            "context": {"velocity": 1.0}
                        },
                        "bass": {"pattern": "bassRiff"},
                        "lead": {
                            "context": {"octave": 5, "velocity": 1.0},
                            "events": [
                                {"t": 1.0, "d": 5, "dur": 2.0, "dynamics": "ff"},
                                {"t": 3.0, "d": 3, "dur": 2.0, "dynamics": "ff"}
                            ]
                        }
                    }
                },
                "bridge": {
                    "context": {"chord": "Am", "dynamics": "mp"},
                    "layers": {
                        "drums": {
                            "events": [
                                {"t": 1.0, "n": "kick", "v": 0.6},
                                {"t": 3.0, "n": "snare", "v": 0.5}
                            ]
                        },
                        "acoustic": {
                            "context": {"octave": 4, "articulation": "legato"},
                            "events": [
                                {"t": 1.0, "d": 1, "dur": 1.0, "v": 0.6},
                                {"t": 2.0, "d": 3, "dur": 1.0, "v": 0.6},
                                {"t": 3.0, "d": 5, "dur": 1.0, "v": 0.6},
                                {"t": 4.0, "d": 3, "dur": 1.0, "v": 0.6}
                            ]
                        }
                    }
                }
            },
            "arrangement": ["verse", "verse", "chorus", "verse", "chorus", "bridge", "chorus", "chorus"]
        })";
        
        auto musician = std::make_unique<Musician>("rock-test", "rock");
        auto result = musician->convertNotationToMidiEvents(rockSong, 130.0);
        
        expect(result.getProperty("success", false), "Rock song should parse successfully");
        expect((double)result.getProperty("tempo", 0.0) == 130.0, "Should preserve tempo");
        
        logMessage("Rock song structure working");
    }
    
    void testClassicalPhrasing()
    {
        beginTest("Classical - Mozart style phrasing");
        
        juce::String mozartStyle = R"({
            "version": "2.0",
            "meta": {
                "title": "Mozart Style Sonata",
                "tempo": 120,
                "style": "classical",
                "timeSignature": "4/4"
            },
            "context": {
                "key": "C major",
                "velocity": 0.7,
                "dynamics": "mp",
                "articulation": "legato"
            },
            "patterns": {
                "melody": {
                    "context": {"octave": 5},
                    "events": [
                        {"t": 1.0, "d": 1, "dur": 1.0, "v": 0.8, "articulation": "legato"},
                        {"t": 2.0, "d": 2, "dur": 0.5, "v": 0.7, "articulation": "legato"},
                        {"t": 2.5, "d": 3, "dur": 0.5, "v": 0.7, "articulation": "legato"},
                        {"t": 3.0, "d": 4, "dur": 1.0, "v": 0.8, "articulation": "tenuto"},
                        {"t": 4.0, "d": 3, "dur": 1.0, "v": 0.7, "articulation": "legato"}
                    ]
                },
                "accompaniment": {
                    "context": {"octave": 4},
                    "events": [
                        {"t": 1.0, "d": 1, "dur": 0.25, "v": 0.5, "articulation": "staccato"},
                        {"t": 1.5, "d": 3, "dur": 0.25, "v": 0.5, "articulation": "staccato"},
                        {"t": 2.0, "d": 5, "dur": 0.25, "v": 0.5, "articulation": "staccato"},
                        {"t": 2.5, "d": 3, "dur": 0.25, "v": 0.5, "articulation": "staccato"},
                        {"t": 3.0, "d": 1, "dur": 0.25, "v": 0.5, "articulation": "staccato"},
                        {"t": 3.5, "d": 3, "dur": 0.25, "v": 0.5, "articulation": "staccato"},
                        {"t": 4.0, "d": 5, "dur": 0.25, "v": 0.5, "articulation": "staccato"},
                        {"t": 4.5, "d": 3, "dur": 0.25, "v": 0.5, "articulation": "staccato"}
                    ]
                },
                "bass": {
                    "context": {"octave": 2},
                    "events": [
                        {"t": 1.0, "d": 1, "dur": 2.0, "v": 0.6, "articulation": "legato"},
                        {"t": 3.0, "d": 5, "dur": 2.0, "v": 0.6, "articulation": "legato"}
                    ]
                }
            },
            "sections": {
                "exposition": {
                    "context": {"chord": "C", "dynamics": "mp"},
                    "layers": {
                        "melody": {"pattern": "melody"},
                        "accompaniment": {"pattern": "accompaniment"},
                        "bass": {"pattern": "bass"}
                    }
                },
                "development": {
                    "context": {"chord": "Am", "dynamics": "mf"},
                    "layers": {
                        "melody": {
                            "pattern": "melody",
                            "context": {"velocity": 0.9}
                        },
                        "accompaniment": {"pattern": "accompaniment"},
                        "bass": {
                            "pattern": "bass",
                            "context": {"chord": "Am"}
                        }
                    }
                },
                "recapitulation": {
                    "context": {"chord": "C", "dynamics": "f"},
                    "layers": {
                        "melody": {
                            "pattern": "melody",
                            "context": {"velocity": 1.0}
                        },
                        "accompaniment": {"pattern": "accompaniment"},
                        "bass": {"pattern": "bass"}
                    }
                }
            },
            "arrangement": ["exposition", "development", "recapitulation"]
        })";
        
        auto musician = std::make_unique<Musician>("classical-test", "classical");
        auto result = musician->convertNotationToMidiEvents(mozartStyle, 120.0);
        
        expect(result.getProperty("success", false), "Classical pattern should parse successfully");
        
        logMessage("Classical phrasing working");
    }
    
    void testElectronicGroove()
    {
        beginTest("Electronic - Techno groove with automation");
        
        juce::String technoGroove = R"({
            "version": "2.0",
            "meta": {
                "title": "Techno Groove",
                "tempo": 128,
                "style": "techno"
            },
            "context": {
                "velocity": 0.9,
                "dynamics": "f"
            },
            "patterns": {
                "kickPattern": {
                    "events": [
                        {"t": 1.0, "n": "kick", "v": 1.0, "dur": 0.25},
                        {"t": 2.0, "n": "kick", "v": 0.8, "dur": 0.25},
                        {"t": 3.0, "n": "kick", "v": 1.0, "dur": 0.25},
                        {"t": 4.0, "n": "kick", "v": 0.8, "dur": 0.25}
                    ]
                },
                "synthLead": {
                    "context": {"octave": 5},
                    "events": [
                        {
                            "t": 1.0, "n": "C", "v": 0.9, "dur": 4.0,
                            "processors": {
                                "filter": {"cutoff": 0.7, "resonance": 0.5},
                                "delay": {"time": 0.125, "feedback": 0.3}
                            },
                            "automation": {
                                "filter.cutoff": [
                                    {"t": 0.0, "v": 0.3},
                                    {"t": 2.0, "v": 1.0},
                                    {"t": 4.0, "v": 0.3}
                                ]
                            }
                        }
                    ]
                },
                "acidBass": {
                    "context": {"octave": 2},
                    "events": [
                        {
                            "t": 1.0, "d": 1, "v": 0.8, "dur": 0.25,
                            "processors": {"acid": {"cutoff": 0.6, "distortion": 0.4}}
                        },
                        {
                            "t": 1.25, "d": 1, "v": 0.6, "dur": 0.25,
                            "processors": {"acid": {"cutoff": 0.4, "distortion": 0.4}}
                        },
                        {
                            "t": 1.5, "d": 3, "v": 0.7, "dur": 0.25,
                            "processors": {"acid": {"cutoff": 0.8, "distortion": 0.4}}
                        },
                        {
                            "t": 2.0, "d": 1, "v": 0.8, "dur": 0.5,
                            "processors": {"acid": {"cutoff": 0.9, "distortion": 0.6}}
                        }
                    ]
                }
            },
            "sections": {
                "drop": {
                    "context": {"chord": "Am", "dynamics": "ff"},
                    "layers": {
                        "kick": {"pattern": "kickPattern"},
                        "synth": {"pattern": "synthLead"},
                        "bass": {"pattern": "acidBass"}
                    }
                }
            }
        })";
        
        auto musician = std::make_unique<Musician>("electronic-test", "electronic");
        auto result = musician->convertNotationToMidiEvents(technoGroove, 128.0);
        
        expect(result.getProperty("success", false), "Electronic groove should parse successfully");
        
        logMessage("Electronic groove with automation working");
    }
    
    void testLLMGeneratedPattern()
    {
        beginTest("LLM-Generated - Complex multi-style pattern");
        
        // This represents what an LLM might generate for a complex request
        juce::String llmPattern = R"({
            "version": "2.0",
            "meta": {
                "title": "AI Fusion Experiment",
                "tempo": 120,
                "style": "fusion",
                "description": "Generated by LLM for jazz-rock fusion with electronic elements"
            },
            "context": {
                "key": "C major",
                "complexity": 0.8,
                "energy": 0.7,
                "velocity": 0.75
            },
            "patterns": {
                "fusionGroove": {
                    "events": [
                        {"t": 1.0, "n": "kick", "v": 0.8, "dur": 0.25},
                        {"t": 1.5, "n": "hihat", "v": 0.4, "dur": 0.1},
                        {"t": 2.0, "n": "snare", "v": 0.7, "dur": 0.25},
                        {"t": 2.75, "n": "kick", "v": 0.6, "dur": 0.25},
                        {"t": 3.0, "n": "hihat", "v": 0.5, "dur": 0.1},
                        {"t": 3.5, "n": "snare", "v": 0.8, "dur": 0.25},
                        {"t": 4.0, "n": "kick", "v": 0.9, "dur": 0.25}
                    ]
                },
                "synthPad": {
                    "context": {"octave": 4, "articulation": "legato"},
                    "events": [
                        {
                            "t": 1.0, "d": 1, "v": 0.6, "dur": 8.0,
                            "expression": {
                                "dynamics": "mp",
                                "vibrato": {"rate": 4, "depth": 0.1}
                            },
                            "processors": {
                                "reverb": {"room": 0.8, "decay": 5.0},
                                "chorus": {"rate": 0.5, "depth": 0.3}
                            }
                        },
                        {
                            "t": 3.0, "d": 5, "v": 0.5, "dur": 6.0,
                            "expression": {
                                "dynamics": "pp",
                                "vibrato": {"rate": 4, "depth": 0.1}
                            }
                        }
                    ]
                },
                "jazzBass": {
                    "context": {"octave": 2, "articulation": "legato"},
                    "events": [
                        {"t": 1.0, "d": 1, "v": 0.8, "dur": 1.0},
                        {"t": 2.0, "d": 3, "v": 0.7, "dur": 0.5},
                        {"t": 2.5, "d": 4, "v": 0.6, "dur": 0.5},
                        {"t": 3.0, "d": 5, "v": 0.8, "dur": 1.0},
                        {"t": 4.0, "d": 7, "v": 0.7, "dur": 1.0}
                    ]
                }
            },
            "sections": {
                "intro": {
                    "context": {"dynamics": "pp", "chord": "Cmaj7"},
                    "layers": {
                        "pad": {"pattern": "synthPad"}
                    }
                },
                "main": {
                    "context": {"dynamics": "mf", "chord": "Cmaj7"},
                    "layers": {
                        "drums": {"pattern": "fusionGroove"},
                        "bass": {"pattern": "jazzBass"},
                        "pad": {"pattern": "synthPad"},
                        "lead": {
                            "context": {"octave": 5, "velocity": 0.9},
                            "events": [
                                {
                                    "t": 1.5, "d": 3, "v": 0.8, "dur": 1.5,
                                    "expression": {
                                        "dynamics": "f",
                                        "articulation": "legato",
                                        "bend": {"amount": 1, "duration": 0.5}
                                    }
                                },
                                {
                                    "t": 3.0, "d": 1, "v": 0.9, "dur": 2.0,
                                    "expression": {
                                        "dynamics": "ff",
                                        "vibrato": {"rate": 6, "depth": 0.3}
                                    }
                                }
                            ]
                        }
                    }
                },
                "breakdown": {
                    "context": {"dynamics": "mp", "chord": "Am7"},
                    "layers": {
                        "bass": {
                            "pattern": "jazzBass",
                            "context": {"chord": "Am7"}
                        },
                        "ambient": {
                            "context": {"octave": 6, "velocity": 0.4},
                            "events": [
                                {
                                    "t": 1.0, "d": 1, "v": 0.3, "dur": 4.0,
                                    "processors": {
                                        "reverb": {"room": 1.0, "decay": 8.0},
                                        "delay": {"time": 0.75, "feedback": 0.6}
                                    }
                                }
                            ]
                        }
                    }
                }
            },
            "arrangement": ["intro", "main", "main", "breakdown", "main"]
        })";
        
        auto musician = std::make_unique<Musician>("llm-test", "fusion");
        auto result = musician->convertNotationToMidiEvents(llmPattern, 120.0);
        
        expect(result.getProperty("success", false), "LLM-generated pattern should parse successfully");
        
        auto events = result["events"];
        if (events.isArray()) {
            expect(events.getArray()->size() > 0, "Should generate complex fusion events");
            logMessage("Generated " + juce::String(events.getArray()->size()) + " fusion events");
        }
        
        logMessage("LLM-generated complex pattern working");
    }
};

// Register the test
static MusicJson2RealWorldTests musicJson2RealWorldTests;

} // namespace covertracks